import { Fragment, useRef } from 'react';
import { useGSAP } from '@gsap/react';
import { gsap } from '@/hooks/useGSAPSetup';
import { useReducedMotion } from '@/hooks/useReducedMotion';

export default function Marquee({ text, speed = 18, reverse = false, className = '' }) {
  const root = useRef(null);
  const reducedMotion = useReducedMotion();

  useGSAP(
    () => {
      if (reducedMotion) return;
      const [track] = gsap.utils.selector(root)('.marquee-track');
      gsap.fromTo(
        track,
        { xPercent: reverse ? -50 : 0 },
        { xPercent: reverse ? 0 : -50, duration: speed, ease: 'none', repeat: -1 }
      );
    },
    { scope: root, dependencies: [text, speed, reverse, reducedMotion], revertOnUpdate: true }
  );

  const phrase = text.split('•').map((part, index) => (
    <Fragment key={index}>
      {index > 0 && <span className="text-(--text-secondary)">•</span>}
      {part}
    </Fragment>
  ));
  const row = [...Array(4)].map((_, i) => (
    <span key={i} className="mx-6 whitespace-nowrap">
      {phrase} <span className="mx-3 text-(--text-secondary)">•</span>
    </span>
  ));

  return (
    <div
      ref={root}
      className={`overflow-hidden border-y border-[rgba(255,255,255,0.08)] bg-(--bg-void) py-4 font-display text-5xl font-semibold uppercase text-(--text-primary) ${className}`}
    >
      <span className="sr-only">{text}</span>
      {reducedMotion ? (
        <p className="px-6 whitespace-normal break-words" aria-hidden="true">{phrase}</p>
      ) : (
        <div className="marquee-track inline-flex will-transform" aria-hidden="true">
          <div className="flex shrink-0">{row}</div>
          <div className="flex shrink-0">{row}</div>
        </div>
      )}
    </div>
  );
}

