import { useRef } from 'react';
import { useTranslation } from 'react-i18next';
import { useGSAP } from '@gsap/react';
import { gsap, ScrollTrigger, revealHeadings } from '@/hooks/useGSAPSetup';
import { useReducedMotion } from '@/hooks/useReducedMotion';
import { PORTFOLIO_DATA } from '@/data';

export default function Experience() {
  const root = useRef(null);
  const { t, i18n } = useTranslation();
  const reducedMotion = useReducedMotion();

  useGSAP((context, contextSafe) => {
    if (!reducedMotion) {
      revealHeadings(root.current.querySelectorAll('h2,h3'), contextSafe);
      const cards = gsap.utils.toArray('[data-mission]', root.current);
      const targets = gsap.utils.toArray('[data-experience-reveal], [data-mission]', root.current)
        .filter((target) => target.getBoundingClientRect().top >= window.innerHeight * 0.85);
      // Opacity keeps the log accessible to screen readers before its visual reveal.
      if (targets.length) gsap.set(targets, { y: 40, opacity: 0 });
      const pendingCards = cards.filter((card) => targets.includes(card));
      if (pendingCards.length) gsap.set(pendingCards, {
        x: (index, card) => cards.indexOf(card) % 2 ? 40 : -40,
      });
      const reveal = contextSafe((batch) => gsap.to(batch, {
        x: 0, y: 0, opacity: 1, duration: 1, ease: 'power3.out', stagger: 0.1, overwrite: 'auto',
      }));
      ScrollTrigger.batch(targets, {
        start: 'top 85%', once: true, onEnter: reveal, onEnterBack: reveal,
      });
    }

    ScrollTrigger.refresh(true);
  }, { scope: root, dependencies: [reducedMotion, i18n.resolvedLanguage], revertOnUpdate: true });

  return (
    <section
      ref={root}
      id="experience"
      lang={i18n.resolvedLanguage}
      data-theme="dark"
      aria-labelledby="experience-heading"
      className="relative overflow-clip border-y border-white/[0.06] bg-(--bg-void) px-6 py-24 text-(--text-primary) sm:px-8 lg:px-12 lg:py-32"
    >
      <div className="mx-auto max-w-7xl">
        <header className="mb-12 max-w-4xl lg:mb-16">
          <p lang="en" data-experience-reveal className="mb-5 font-mono text-xs tracking-[0.2em] text-(--text-secondary)">
            {t('experience.sectionLabel')}
          </p>
          <h2 key={i18n.resolvedLanguage} aria-label={t('experience.heading')} id="experience-heading" className="split-heading font-display text-[clamp(1.75rem,4.5vw,4rem)] font-bold uppercase leading-[1.2] tracking-[-0.035em]">
            {t('experience.heading')}
          </h2>
        </header>

        <ol role="list" className="m-0 grid list-none grid-cols-1 gap-5 p-0 lg:grid-cols-3 lg:gap-6">
          {PORTFOLIO_DATA.experience.map(({ id }) => {
            const position = t(`experience.positions.${id}`, { returnObjects: true });
            return (
              <li key={id} data-mission className="min-w-0">
                <article aria-labelledby={`mission-${id}`} className="flex h-full flex-col border border-white/10 bg-(--bg-surface) p-6 hover:border-white/35 xl:p-8">
                  <h3 key={i18n.resolvedLanguage} aria-label={position.company} id={`mission-${id}`} className="split-heading font-display text-xl font-semibold leading-tight tracking-[-0.035em] [overflow-wrap:anywhere] 2xl:text-2xl">
                    {position.company}
                  </h3>
                  <p lang="en" className="mt-3 font-mono text-xs leading-relaxed text-(--text-secondary) sm:text-sm lg:text-xs">
                    {position.role}
                  </p>
                  <div className="mt-6 flex flex-wrap items-center gap-3">
                    <p className="font-mono text-xs leading-relaxed text-(--text-secondary)">{position.period}</p>
                    <span lang="en" className="inline-flex border border-white/20 px-2.5 py-1 font-mono text-[11px] leading-relaxed tracking-[0.03em]">
                      {position.type}
                    </span>
                  </div>
                  <p className="mt-6 border-t border-white/[0.06] pt-6 font-body text-base leading-[1.75] text-(--text-secondary)">
                    {position.description}
                  </p>
                </article>
              </li>
            );
          })}
        </ol>
      </div>
    </section>
  );
}

