import { useRef } from 'react';
import { useTranslation } from 'react-i18next';
import { useGSAP } from '@gsap/react';
import { gsap, ScrollTrigger, revealHeadings } from '@/hooks/useGSAPSetup';
import { useReducedMotion } from '@/hooks/useReducedMotion';
import { LiveDemo } from '@/components/effects/LiveDemo';

const experiments = [
  ['starfieldExplorer', 'lg:col-span-7'],
  ['nebulaShaderPlayground', 'lg:col-span-5'],
  ['scrollProgressOrbit', 'lg:col-span-6'],
  ['magneticField', 'lg:col-span-3'],
  ['textScrambleLab', 'lg:col-span-3'],
  ['constellationGrid', 'lg:col-span-4'],
  ['wormholeTunnel', 'lg:col-span-4'],
  ['marqueeGenerator', 'lg:col-span-4'],
];

export default function Playground() {
  const root = useRef(null);
  const reducedMotion = useReducedMotion();
  const { t, i18n } = useTranslation();

  useGSAP((context, contextSafe) => {
    if (!reducedMotion) {
      revealHeadings(root.current.querySelectorAll('h2,h3'), contextSafe);
      const targets = gsap.utils.toArray('[data-playground-reveal], [data-experiment]', root.current)
        .filter((target) => target.getBoundingClientRect().top >= window.innerHeight * 0.9);
      if (targets.length) gsap.set(targets, { y: 40, opacity: 0 });
      const reveal = contextSafe((batch) => gsap.to(batch, {
        y: 0, opacity: 1, duration: 1, stagger: 0.1, ease: 'power3.out', overwrite: 'auto',
      }));
      ScrollTrigger.batch(targets, {
        id: 'playground-reveal', start: 'top 90%', once: true,
        onEnter: reveal, onEnterBack: reveal,
      });
    }
    ScrollTrigger.refresh(true);
  }, { scope: root, dependencies: [reducedMotion, i18n.resolvedLanguage], revertOnUpdate: true });

  return (
    <section ref={root} id="playground" lang={i18n.resolvedLanguage} data-theme="dark" aria-labelledby="playground-heading" className="relative border-t border-white/10 bg-(--bg-void) px-5 py-24 text-(--text-primary) sm:px-8 lg:px-12 lg:py-32">
